import numpy as np
def softmax(z):
    e = np.exp(z - np.max(z))
    return e / e.sum()
# softmax turns scores into class probabilities that sum to 1
print(np.round(softmax(np.array([2.0, 1.0, 0.1])), 4).tolist())

